const STORAGE_KEYS = { USER: 'crm_session_user', VIEW: 'crm_last_view', LAST_ACTIVE: 'crm_last_active' };
const INACTIVITY_TIMEOUT = 30 * 60 * 1000; 

const App: React.FC = () => {
  const [view, setViewState] = useState<ViewState>('landing');
  const [lang, setLang] = useState<Language>('fa');
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [services, setServices] = useState<ServiceOption[]>([]);
  const [personnel, setPersonnel] = useState<Personnel[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [messages, setMessages] = useState<InternalMessage[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [meetings, setMeetings] = useState<Meeting[]>([]);
  const [kpis, setKpis] = useState<KPI[]>([]);
  const [objectives, setObjectives] = useState<StrategicObjective[]>([]);
  const [currentUser, setCurrentUser] = useState<Personnel | null>(null);
  const [appConfig, setAppConfig] = useState<AppConfig>(INITIAL_CONFIG);
  const [isLoadingData, setIsLoadingData] = useState(true);

  const t = DICTIONARY[lang];

  const setView = (newView: ViewState) => {
    setViewState(newView);
    localStorage.setItem(STORAGE_KEYS.VIEW, newView);
  };

  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';
  }, [lang]);

  useEffect(() => {
    const unsubTickets = subscribeToTickets(setTickets);
    const unsubCustomers = subscribeToCustomers(setCustomers);
    const unsubMessages = subscribeToMessages(setMessages);
    const unsubTasks = subscribeToTasks(setTasks);
    const unsubMeetings = subscribeToMeetings(setMeetings);
    const unsubKPIs = subscribeToKPIs(setKpis);
    const unsubObjectives = subscribeToObjectives(setObjectives);
    const unsubSettings = subscribeToSettings(
      (cfg) => { if (cfg) setAppConfig(cfg); },
      (srv) => { if (srv) setServices(srv); },
      (ppl) => { if (ppl) setPersonnel(ppl); setIsLoadingData(false); }
    );
    return () => { unsubTickets(); unsubCustomers(); unsubSettings(); unsubMessages(); unsubTasks(); unsubMeetings(); unsubKPIs(); unsubObjectives(); };
  }, []);

  const handleNewTicket = async (ticketOrTickets: Ticket | Ticket[]) => {
     if (Array.isArray(ticketOrTickets)) {
         for (const t of ticketOrTickets) await saveTicketToCloud(t);
     } else await saveTicketToCloud(ticketOrTickets);
  };

  const handleUpdateTicket = async (id: string, updates: Partial<Ticket>, actorName: string, actionNote?: string, visibility: 'public' | 'internal' = 'public') => {
    await updateTicketInCloud(id, updates);
  };

  const handleLogin = async (u: string, p: string): Promise<boolean> => {
    const user = personnel.find(person => person.username === u && person.password === p);
    if (user) {
      setCurrentUser(user);
      logSystemAction('LOGIN', 'System', 'ورود کاربر به سیستم', user.fullName, user.id);
      localStorage.setItem(STORAGE_KEYS.USER, JSON.stringify(sanitizeData(user)));
      localStorage.setItem(STORAGE_KEYS.LAST_ACTIVE, Date.now().toString());
      return true;
    }
    return false;
  };

  const handleLogout = () => {
    setCurrentUser(null); setView('landing');
    localStorage.removeItem(STORAGE_KEYS.USER); localStorage.removeItem(STORAGE_KEYS.VIEW); localStorage.removeItem(STORAGE_KEYS.LAST_ACTIVE);
  };

  return (
    <div className={`min-h-screen bg-gray-50 flex flex-col font-sans ${lang === 'fa' ? 'font-vazir' : ''}`} dir={lang === 'fa' ? 'rtl' : 'ltr'}>
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('landing')}>
            <div className="bg-indigo-600 text-white p-2 rounded-lg"><IconShield className="w-6 h-6" /></div>
            <div>
              <h1 className="text-xl font-bold text-gray-900">{lang === 'fa' ? appConfig.appTitle : appConfig.appTitleEn}</h1>
              <p className="text-xs text-gray-500">{lang === 'fa' ? appConfig.appSubtitle : appConfig.appSubtitleEn}</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <nav className="hidden md:flex gap-2">
              <button onClick={() => setView('new-ticket')} className={`px-4 py-2 rounded-lg font-medium ${view === 'new-ticket' ? 'bg-indigo-600 text-white' : 'text-gray-600 hover:bg-gray-100'}`}>{t.newTicket}</button>
              <button onClick={() => setView('tracking')} className={`px-4 py-2 rounded-lg font-medium ${view === 'tracking' ? 'bg-indigo-600 text-white' : 'text-gray-600 hover:bg-gray-100'}`}>{t.tracking}</button>
              <button onClick={() => setView('admin')} className={`px-4 py-2 rounded-lg font-medium ${view === 'admin' ? 'bg-indigo-600 text-white' : 'text-gray-600 hover:bg-gray-100'}`}>{t.expertPanel}</button>
            </nav>
          </div>
        </div>
      </header>

      <main className="flex-grow p-4 md:p-8 max-w-7xl mx-auto w-full">
        {isLoadingData ? (
           <div className="flex items-center justify-center h-64"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>
        ) : (
          <>
            {view === 'landing' && (
              <div className="animate-fade-in text-center py-20">
                  <h2 className="text-4xl md:text-6xl font-black text-gray-900 mb-6">{lang === 'fa' ? appConfig.landingHeroTitle : 'Export Solutions'}</h2>
                  <p className="text-xl text-gray-600 mb-12 max-w-2xl mx-auto">{lang === 'fa' ? appConfig.landingHeroSubtitle : t.landingSubtitle}</p>
                  <div className="flex gap-4 justify-center">
                    <button onClick={() => setView('new-ticket')} className="px-8 py-4 bg-indigo-600 text-white rounded-xl text-lg font-bold shadow-xl">شروع خدمات</button>
                    <button onClick={() => setView('tracking')} className="px-8 py-4 bg-white text-gray-700 border border-gray-200 rounded-xl text-lg font-bold">پیگیری پرونده</button>
                  </div>
              </div>
            )}
            {view === 'new-ticket' && <CustomerForm config={appConfig} services={services.filter(s => s.isActive)} onSubmit={handleNewTicket} onCancel={() => setView('landing')} lang={lang} />}
            {view === 'tracking' && <TrackingView tickets={tickets} services={services} lang={lang} />}
            {view === 'admin' && (
              !currentUser ? <LoginView onLogin={handleLogin} onBack={() => setView('landing')} /> :
              <AdminDashboard lang={lang} currentUser={currentUser} tickets={tickets} services={services} personnel={personnel} customers={customers} messages={messages} tasks={tasks} meetings={meetings} kpis={kpis} config={appConfig} onCreateTicket={async (t) => handleNewTicket(t)} onUpdateTicket={handleUpdateTicket} onDeleteTicket={deleteTicketFromCloud} onUpdateServices={saveServicesToCloud} onUpdatePersonnel={savePersonnelToCloud} onUpdateCustomers={() => {}} onEditCustomer={updateCustomerInCloud} onDeleteCustomer={deleteCustomerFromCloud} onUpdateConfig={saveAppConfigToCloud} onLogout={handleLogout} />
            )}
          </>
        )}
      </main>
      <footer className="bg-white border-t border-gray-200 py-8 text-center text-gray-500 text-sm"><p>{appConfig.footerText || t.footer}</p></footer>
    </div>
  );
};

export default App;

