    { id: 'cat2', title: 'توسعه فردی (Personal)', color: 'header-green', type: 'personal' as const },
    { id: 'cat3', title: 'سلامتی و لایف‌استایل', color: 'header-orange', type: 'personal' as const },
    { id: 'cat4', title: 'اهداف مالی', color: 'header-purple', type: 'personal' as const },
    { id: 'cat5', title: 'سایر موارد', color: 'header-pink', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);

    const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] }))
                });
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => { total++; if (t.isCompleted) done++; });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'ردیاب اهداف هوشمند',
            daily: 'روزانه',
            weekly: 'هفتگی',
            monthly: 'ماهانه',
            yearly: 'سالانه',
            five_year: 'چشم‌انداز ۵ ساله',
            addGoal: 'افزودن هدف',
            done: 'انجام شد',
            total: 'کل',
            progress: 'پیشرفت',
            empty: 'هنوز هدفی ثبت نشده است.',
            masterView: 'مشاهده اهداف پرسنل:',
            lastUpdate: 'آخرین بروزرسانی:',
            addSubTask: 'افزودن گام اجرایی...',
            print: 'خروجی چاپ A4',
            reportTitle: 'برنامه راهبردی و اهداف فردی'
        },
        en: {
            title: 'SMART Goal Tracker',
            daily: 'Daily',
            weekly: 'Weekly',
            monthly: 'Monthly',
            yearly: 'Yearly',
            five_year: '5-Year Vision',
            addGoal: 'Add Goal',
            done: 'Done',
            total: 'Total',
            progress: 'Progress',
            empty: 'No goals set yet.',
            masterView: 'View Staff Goals:',
            lastUpdate: 'Last Updated:',
            addSubTask: 'Add step...',
            print: 'Print A4 Poster',
            reportTitle: 'Strategic Goals'
        }
    }[lang];

    const handleAddTask = (catId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const taskText = window.prompt(lang === 'fa' ? 'عنوان هدف را وارد کنید:' : 'Enter goal title:');
        if (!taskText) return;
        const updatedCategories = currentUserGoals.categories.map(c => 
            c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text: taskText, isCompleted: false, subTasks: [] }] } : c
        );
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!canEdit || !currentUserGoals) return;
        const updatedCategories = currentUserGoals.categories.map(c => 
            c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, isCompleted: !t.isCompleted } : t) } : c
        );
        const updatedGoals = { ...currentUserGoals, categories: updatedCategories, lastUpdated: new Date().toISOString() };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    if (isLoading) return <div className="p-8 text-center">در حال بارگذاری...</div>;

    return (
        <div className="space-y-8 animate-fade-in pb-12">
            <div className="bg-white p-8 rounded-3xl shadow-xl border border-gray-100 flex flex-col lg:flex-row gap-8 items-center print:hidden">
                <div className="shrink-0 w-full lg:w-1/3">
                    <h2 className="text-3xl font-black text-gray-900 mb-2">{t.title}</h2>
                    <div className="flex bg-gray-100 p-1 rounded-2xl mb-6 overflow-x-auto">
                        {(['daily', 'weekly', 'monthly', 'yearly', 'five_year'] as GoalPeriod[]).map(p => (
                            <button key={p} onClick={() => setActivePeriod(p)} className={`flex-1 py-2 rounded-xl text-[10px] font-black transition-all ${activePeriod === p ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>{t[p]}</button>
                        ))}
                    </div>
                    {isMaster && (
                        <div className="mb-4">
                            <label className="text-xs font-bold text-gray-400 block mb-1">{t.masterView}</label>
                            <select className="w-full border rounded-lg p-2 text-sm" value={selectedUserId} onChange={(e) => setSelectedUserId(e.target.value)}>
                                {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                            </select>
                        </div>
                    )}
                    <button onClick={() => window.print()} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-xs font-black flex items-center justify-center gap-2 shadow-lg"><IconPrinter className="w-4 h-4" /> {t.print}</button>
                </div>
                <div className="flex flex-col items-center gap-2 lg:border-r lg:px-8 border-gray-100">
                    <div className="relative w-32 h-32 flex items-center justify-center">
                        <svg className="w-full h-full transform -rotate-90">
                            <circle cx="64" cy="64" r="54" stroke="currentColor" strokeWidth="10" fill="transparent" className="text-gray-100" />
                            <circle cx="64" cy="64" r="54" stroke="currentColor" strokeWidth="10" fill="transparent" strokeDasharray={339.292} strokeDashoffset={339.292 - (stats.percent/100)*339.292} className="text-indigo-600" />
                        </svg>
                        <div className="absolute inset-0 flex flex-col items-center justify-center"><span className="text-2xl font-black">{stats.percent}%</span></div>
                    </div>
                </div>
                <div className="flex-grow grid grid-cols-2 sm:grid-cols-3 gap-4 w-full">
                    {currentUserGoals?.categories.map(cat => {
                        const prog = cat.tasks.length > 0 ? Math.round((cat.tasks.filter(t => t.isCompleted).length / cat.tasks.length) * 100) : 0;
                        return (
                            <div key={cat.id} className="bg-gray-50 p-3 rounded-2xl border border-gray-100">
                                <div className="text-[9px] font-black text-gray-400 uppercase mb-1">{cat.title}</div>
                                <div className="w-full bg-gray-200 h-1.5 rounded-full overflow-hidden"><div className="bg-indigo-600 h-full" style={{ width: `${prog}%` }}></div></div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-6 print:hidden">
                {currentUserGoals?.categories.map((cat) => (
                    <div key={cat.id} className="bg-white rounded-3xl border border-gray-100 shadow-lg overflow-hidden flex flex-col min-h-[400px]">
                        <div className="bg-indigo-600 p-4 text-center text-white font-black text-xs uppercase">{cat.title}</div>
                        <div className="flex-grow p-4 space-y-3 overflow-y-auto">
                            {cat.tasks.map((task) => (
                                <div key={task.id} className={`flex items-start gap-3 p-3 rounded-2xl border ${task.isCompleted ? 'bg-gray-50' : 'bg-white shadow-sm'}`}>
                                    <button onClick={() => toggleTask(cat.id, task.id)} className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center shrink-0 mt-0.5 ${task.isCompleted ? 'bg-green-500 border-green-500 text-white' : 'border-gray-200'}`}>{task.isCompleted && <IconCheck className="w-3 h-3"/>}</button>
                                    <span className={`text-[12px] font-bold ${task.isCompleted ? 'text-gray-300 line-through' : 'text-gray-700'}`}>{task.text}</span>
                                </div>
                            ))}
                        </div>
                        {canEdit && <div className="p-4 border-t border-gray-50"><button onClick={() => handleAddTask(cat.id)} className="w-full py-2.5 rounded-xl border-2 border-dashed border-gray-200 text-gray-400 font-black text-[11px] hover:border-indigo-300 transition-all flex items-center justify-center gap-2"><IconPlus className="w-4 h-4" /> {t.addGoal}</button></div>}
                    </div>
                ))}
            </div>
        </div>
    );
};
